"use client";

import { useEffect, useState } from "react";

import { getPipelineStatus, runPipeline } from "@/lib/api/pipeline";

import { Button } from "@/components/ui/button";
import { Loader2, Play } from "lucide-react";

export default function PipelinePage() {
  const [status, setStatus] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  async function fetchStatus() {
    const data = await getPipelineStatus();
    setStatus(data);
  }

  useEffect(() => {
    fetchStatus();

    const interval = setInterval(fetchStatus, 5000);

    return () => clearInterval(interval);
  }, []);

  async function handleRun() {
    setLoading(true);

    await runPipeline();

    await fetchStatus();

    setLoading(false);
  }

  return (
    <div className="space-y-6 p-6">
      <h1 className="text-3xl font-bold text-white">Pipeline Control</h1>

      <div className="bg-[#222] border border-[#333] rounded-lg p-6 space-y-4">
        <div>
          <p className="text-gray-400 text-sm">Status</p>
          <p className="text-xl text-white font-semibold">
            {status?.status || "Unknown"}
          </p>
        </div>

        <div>
          <p className="text-gray-400 text-sm">Started At</p>
          <p className="text-white">
            {status?.startedAt
              ? new Date(status.startedAt).toLocaleString()
              : "-"}
          </p>
        </div>

        <div>
          <p className="text-gray-400 text-sm">Last Finished</p>
          <p className="text-white">
            {status?.finishedAt
              ? new Date(status.finishedAt).toLocaleString()
              : "-"}
          </p>
        </div>

        <Button
          onClick={handleRun}
          disabled={loading || status?.status === "RUNNING"}
          className="gap-2"
        >
          {loading || status?.status === "RUNNING" ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin" />
              Pipeline Running
            </>
          ) : (
            <>
              <Play className="h-4 w-4" />
              Run Pipeline
            </>
          )}
        </Button>
      </div>
    </div>
  );
}
